def canAttendMeetings(intervals: List[List[int]]) -> bool:
    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            s1, e1 = intervals[i]
            s2, e2 = intervals[j]
            if max(s1, s2) < min(e1, e2):
                return False
    return True

