def generate(rng, n):
    intervals = []
    curr = 0
    for _ in range(n):
        start = curr + rng.randint(0, 5)
        end = start + rng.randint(1, 5)
        intervals.append([start, end])
        curr = end
    rng.shuffle(intervals)
    return [intervals]

def generate_worst(rng, n):
    intervals = []
    for i in range(n):
        intervals.append([0, 10])
    return [intervals]

